import unittest
from candidate import digitSum

class TestDigitSum(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(digitSum(""), 0)

    def test_no_uppercase_chars(self):
        self.assertEqual(digitSum("abcdef"), 0)

    def test_single_uppercase_char(self):
        self.assertEqual(digitSum("A"), 65)

    def test_multiple_uppercase_chars(self):
        self.assertEqual(digitSum("ABC"), 65 + 66 + 67)

    def test_mixed_case_string(self):
        self.assertEqual(digitSum("abAB"), 65 + 66 + 65 + 66)

    def test_case_with_decimal(self):
        self.assertEqual(digitSum("aBcD123"), 65 + 66 + 68)

    def test_case_with_numbers(self):
        self.assertEqual(digitSum("123A45B"), 65 + 66)

    def test_case_with_special_chars(self):
        self.assertEqual(digitSum("!@#ABC"), 65 + 66 + 67)

    def test_case_with_lowercase_and_uppercase_mixed(self):
        self.assertEqual(digitSum("aAaaaXa"), 65 + 65 + 65 + 88)

    def test_case_with_whitespace(self):
        self.assertEqual(digitSum("a B c D"), 65 + 68)

    def test_case_with_non_ascii_uppercase(self):
        self.assertEqual(digitSum("αΒΓ"), 0)  # Assuming ASCII-only behavior

    def test_case_with_none_input(self):
        with self.assertRaises(TypeError):
            digitSum(None)

    def test_case_with_non_string_input(self):
        with self.assertRaises(TypeError):
            digitSum(123)
        with self.assertRaises(TypeError):
            digitSum([1, 2, 3])

if __name__ == '__main__':
    unittest.main()
